// CommentDeleteOne builds the delete of one `comments` row. Start one with
// `Graph.comments().delete_one(node)` or `delete_one_id(id)`.
pub struct CommentDeleteOne {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete_one starts the delete of the row of `node`.
pub fn (q CommentQuery) delete_one(node CommentNode) CommentDeleteOne {
	return q.delete_one_id(node.comment.id)
}

// delete_one_id starts the delete of the row with the key `id`.
pub fn (q CommentQuery) delete_one_id(id i64) CommentDeleteOne {
	return CommentDeleteOne{
		graph: q.graph
		data:  vgraph.MutationData{
			op:      .delete_one
			table:   'comments'
			row_key: id.str()
		}
	}
}

// exec deletes the row, with its join table rows, in one transaction, or
// returns a `NotFoundError`.
pub fn (b CommentDeleteOne) exec() ! {
	if !b.graph.client.delete_one(b.data)! {
		return NotFoundError{
			table: 'comments'
		}
	}
}

// CommentDelete builds the delete of the `comments` rows that match its conditions.
// Start one with `Graph.comments().delete()`.
pub struct CommentDelete {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete starts the delete of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q CommentQuery) delete() CommentDelete {
	return CommentDelete{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .delete
			table: 'comments'
			conds: q.query.conds.clone()
		}
	}
}

// where keeps the rows that match every one of `conds`.
pub fn (b CommentDelete) where(conds ...load.Cond) CommentDelete {
